=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v (N = 8). Extends the approved idle testbench:
// a per-cycle reference model (written per bit from the register description in
// the RTL header) is compared against irq, irq_id and all four registers after
// every clock edge, followed by hard-coded directed checks and a seeded random phase.
// No include, pragma, Verilator configuration, file or DPI access is used.
`timescale 1ns / 1ps
module irq_ctrl_cov_tb;
    localparam int N = 8;
    localparam logic [1:0] A_ENABLE = 2'd0, A_MODE = 2'd1, A_PENDING = 2'd2, A_CLAIM = 2'd3;

    logic         clk = 1'b0;
    logic         rst_n = 1'b0;
    logic [N-1:0] src = '0;
    logic         we = 1'b0;
    logic [1:0]   addr = 2'd0;
    logic [31:0]  wdata = 32'd0;
    logic [31:0]  rdata;
    logic         irq;
    logic [4:0]   irq_id;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    // Reference model state.
    logic [N-1:0] m_enable = '0;
    logic [N-1:0] m_mode = '0;
    logic [N-1:0] m_pending = '0;
    logic [N-1:0] m_src_prev = '0;

    // Random stimulus state.
    logic [31:0] rng = 32'h1ACE_B00C;
    logic [31:0] r0, r1, r_data;
    logic [1:0]  r_addr;

    irq_ctrl #(.N(N)) dut (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
                           .rdata(rdata), .irq(irq), .irq_id(irq_id));
    always #10 clk = ~clk;

    // Next pending value, bit by bit: a detection (high level, or rising edge in
    // edge mode) sets the bit; otherwise a PENDING write of 1, or a CLAIM write
    // naming the source, clears it.
    function automatic logic [N-1:0] next_pending(
        input logic [N-1:0] pend, input logic [N-1:0] md, input logic [N-1:0] s,
        input logic [N-1:0] s_prev, input logic w, input logic [1:0] a, input logic [31:0] d);
        logic [N-1:0] nxt;
        logic seen, cleared;
        nxt = '0;
        for (int k = 0; k < N; k++) begin
            seen    = md[k] ? (s[k] && !s_prev[k]) : s[k];
            cleared = w && ((a == A_PENDING && d[k]) || (a == A_CLAIM && int'(d[4:0]) == k));
            nxt[k]  = seen || (pend[k] && !cleared);
        end
        return nxt;
    endfunction

    // Lowest-numbered active source, searched upward.
    function automatic logic [4:0] exp_id(input logic [N-1:0] act);
        logic [4:0] id;
        logic found;
        id = 5'd0;
        found = 1'b0;
        for (int k = 0; k < N; k++) begin
            if (act[k] && !found) begin
                id = 5'(k);
                found = 1'b1;
            end
        end
        return id;
    endfunction

    always @(posedge clk) begin
        if (!rst_n) begin
            m_enable   <= '0;
            m_mode     <= '0;
            m_pending  <= '0;
            m_src_prev <= '0;
        end else begin
            m_pending  <= next_pending(m_pending, m_mode, src, m_src_prev, we, addr, wdata);
            m_src_prev <= src;
            if (we && addr == A_ENABLE) m_enable <= wdata[N-1:0];
            if (we && addr == A_MODE)   m_mode   <= wdata[N-1:0];
        end
    end

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("ERROR t=%0t addr=%0d rdata=%h expected=%h", $time, a, rdata, expected);
        end
    endtask

    task automatic check_model();
        logic [N-1:0] act;
        logic [31:0]  claim;
        act   = m_pending & m_enable;
        claim = {|act, 26'd0, exp_id(act)};
        checks++;
        if (irq !== (|act) || irq_id !== exp_id(act)) begin
            errors++;
            $display("ERROR t=%0t irq=%b irq_id=%0d expected irq=%b irq_id=%0d",
                     $time, irq, irq_id, |act, exp_id(act));
        end
        expect_reg(A_ENABLE,  32'(m_enable));
        expect_reg(A_MODE,    32'(m_mode));
        expect_reg(A_PENDING, 32'(m_pending));
        expect_reg(A_CLAIM,   claim);
    endtask

    // Drive one cycle's inputs, take the clock edge, then compare against the model.
    task automatic cycle(input logic [N-1:0] s, input logic w, input logic [1:0] a, input logic [31:0] d);
        src = s; we = w; addr = a; wdata = d;
        @(posedge clk);
        #1;
        we = 1'b0;
        check_model();
    endtask

    task automatic do_reset(input int cycles_low);
        rst_n = 1'b0; src = '0; we = 1'b0; addr = 2'd0; wdata = 32'd0;
        repeat (cycles_low) @(posedge clk);
        #1;
        rst_n = 1'b1;
        check_model();
        expect_reg(A_ENABLE,  32'h0);
        expect_reg(A_MODE,    32'h0);
        expect_reg(A_PENDING, 32'h0);
        expect_reg(A_CLAIM,   32'h0);
    endtask

    task automatic rand_step();
        rng = rng ^ (rng << 13);
        rng = rng ^ (rng >> 17);
        rng = rng ^ (rng << 5);
    endtask

    initial begin
        // Reset values.
        do_reset(3);

        // Register access: bits N and up are ignored; PENDING and CLAIM writes with nothing pending.
        cycle(8'h00, 1'b1, A_ENABLE,  32'hFFFF_FFFF); expect_reg(A_ENABLE,  32'h0000_00FF);
        cycle(8'h00, 1'b1, A_MODE,    32'hFFFF_FFFF); expect_reg(A_MODE,    32'h0000_00FF);
        cycle(8'h00, 1'b1, A_ENABLE,  32'hAAAA_AAAA); expect_reg(A_ENABLE,  32'h0000_00AA);
        cycle(8'h00, 1'b1, A_MODE,    32'h5555_5555); expect_reg(A_MODE,    32'h0000_0055);
        cycle(8'h00, 1'b1, A_ENABLE,  32'h0000_0000); expect_reg(A_ENABLE,  32'h0);
        cycle(8'h00, 1'b1, A_MODE,    32'h0000_0000); expect_reg(A_MODE,    32'h0);
        cycle(8'h00, 1'b1, A_PENDING, 32'hFFFF_FFFF); expect_reg(A_PENDING, 32'h0);
        cycle(8'h00, 1'b1, A_CLAIM,   32'hFFFF_FFFF); expect_reg(A_CLAIM,   32'h0);

        // Level mode: pends while disabled, irq follows ENABLE, detection wins over a clear.
        cycle(8'h01, 1'b0, A_ENABLE,  32'h0);
        expect_reg(A_PENDING, 32'h1); expect_reg(A_CLAIM, 32'h0);
        cycle(8'h00, 1'b1, A_ENABLE,  32'h0000_00FF);
        expect_reg(A_PENDING, 32'h1); expect_reg(A_CLAIM, 32'h8000_0000);
        cycle(8'h01, 1'b1, A_PENDING, 32'h1);
        expect_reg(A_PENDING, 32'h1);
        cycle(8'h00, 1'b1, A_PENDING, 32'h1);
        expect_reg(A_PENDING, 32'h0); expect_reg(A_CLAIM, 32'h0);

        // Fixed priority: all pending, acknowledge 0..N-1 in turn.
        cycle(8'hFF, 1'b0, A_ENABLE, 32'h0);
        expect_reg(A_PENDING, 32'hFF); expect_reg(A_CLAIM, 32'h8000_0000);
        for (int k = 0; k < N; k++) begin
            cycle(8'h00, 1'b1, A_CLAIM, 32'(k));
            expect_reg(A_CLAIM, (k == N - 1) ? 32'h0 : (32'h8000_0000 | 32'(k + 1)));
        end
        expect_reg(A_PENDING, 32'h0);

        // Masking: active = pending & enable.
        cycle(8'h3C, 1'b0, A_ENABLE, 32'h0);
        expect_reg(A_CLAIM, 32'h8000_0002);
        cycle(8'h00, 1'b1, A_ENABLE, 32'h0000_00F0);
        expect_reg(A_PENDING, 32'h3C); expect_reg(A_CLAIM, 32'h8000_0004);
        cycle(8'h00, 1'b1, A_ENABLE, 32'h0000_000C);
        expect_reg(A_CLAIM, 32'h8000_0002);
        cycle(8'h00, 1'b1, A_PENDING, 32'hFFFF_FFFF);
        expect_reg(A_PENDING, 32'h0); expect_reg(A_CLAIM, 32'h0);
        cycle(8'h00, 1'b1, A_ENABLE, 32'h0000_00FF);

        // Acknowledge out of range is ignored; upper wdata bits are ignored.
        cycle(8'h01, 1'b0, A_ENABLE, 32'h0);
        expect_reg(A_PENDING, 32'h1);
        cycle(8'h00, 1'b1, A_CLAIM, 32'h0000_0008);
        expect_reg(A_PENDING, 32'h1);
        cycle(8'h00, 1'b1, A_CLAIM, 32'h0000_001F);
        expect_reg(A_PENDING, 32'h1);
        cycle(8'h00, 1'b1, A_CLAIM, 32'hFFFF_FFE0);
        expect_reg(A_PENDING, 32'h0);

        // Rising-edge mode.
        cycle(8'h00, 1'b1, A_MODE, 32'h0000_00FF);
        cycle(8'h0F, 1'b0, A_MODE, 32'h0);
        expect_reg(A_PENDING, 32'h0F); expect_reg(A_CLAIM, 32'h8000_0000);
        cycle(8'h0F, 1'b1, A_PENDING, 32'h0000_000F);
        expect_reg(A_PENDING, 32'h0);
        cycle(8'h0F, 1'b0, A_MODE, 32'h0);
        expect_reg(A_PENDING, 32'h0);
        cycle(8'h00, 1'b0, A_MODE, 32'h0);
        expect_reg(A_PENDING, 32'h0);
        cycle(8'hF0, 1'b1, A_CLAIM, 32'h0000_0004);
        expect_reg(A_PENDING, 32'hF0); expect_reg(A_CLAIM, 32'h8000_0004);
        cycle(8'hF0, 1'b1, A_CLAIM, 32'h0000_0004);
        expect_reg(A_PENDING, 32'hE0); expect_reg(A_CLAIM, 32'h8000_0005);

        // Mixed modes: bits 3:0 edge, bits 7:4 level.
        cycle(8'h00, 1'b1, A_PENDING, 32'h0000_00FF);
        expect_reg(A_PENDING, 32'h0);
        cycle(8'h00, 1'b1, A_MODE, 32'h0000_000F);
        cycle(8'hFF, 1'b0, A_MODE, 32'h0);
        expect_reg(A_PENDING, 32'hFF);
        cycle(8'hFF, 1'b1, A_PENDING, 32'h0000_00FF);
        expect_reg(A_PENDING, 32'hF0); expect_reg(A_CLAIM, 32'h8000_0004);
        cycle(8'h00, 1'b1, A_PENDING, 32'h0000_00FF);
        expect_reg(A_PENDING, 32'h0);
        cycle(8'h00, 1'b1, A_MODE, 32'h0);

        // Seeded random phase, checked against the model every cycle, with a mid-run reset.
        for (int n = 0; n < 400; n++) begin
            if (n == 200) do_reset(2);
            rand_step(); r0 = rng;
            rand_step(); r1 = rng;
            r_addr = r1[3:2];
            r_data = r1;
            if (r_addr == A_CLAIM && r1[4]) r_data = {r1[31:5], exp_id(m_pending & m_enable)};
            cycle(r0[N-1:0] & r0[N+7:8], r1[0], r_addr, r_data);
        end

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
